--------------------------------------------------
-- WeintCodex :: Berufe - Rezepte und Lehrer
--------------------------------------------------
-- ERZEUGT von .github/scripts/import_foreverguide.py - nicht von Hand
-- aendern; neu erzeugen.
--
-- HERKUNFT `community`: das Addon ForeverGuide 1.25.6 hat die Rezepte aus dem
-- Forever-Client gelesen (Build 1.60.1, ueber wowforevertalents.com) und
-- die Lehrer aus der Questie-Datenbank fuer Forever. Uebernommen sind nur
-- Fakten (Nummern, Fertigkeitsstufen, Reagenzien, Lagen). Die Haendler
-- fuer Rezepte stammen aus Classic (cmangos) und heissen so (`classic`).
-- Weggelassen: der Abschnitt "Season of Discovery" - im Client, ob in
-- Forever lernbar, ist nicht belegt.
--
-- REZEPTE als Zeilen, je Beruf ein Text; gelesen erst, wenn die Seite den
-- Beruf zeigt (WeintCodex.ProfessionData.Recipes):
--   Zauber Gegenstand Lernen Gelb Gruen Grau Stand Merkmale Rezept Gunst|Reagenzien|Name
--   Stand: n neu in Forever, c geaendert, s wie Classic
--   Merkmale: t beim Lehrer, b Rezept beim Aufheben gebunden; "-" leer
--   Reagenzien: Nummer:Anzahl, mit Komma
--------------------------------------------------

